<?php
namespace Tests;
use App\Services\SalonStore;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Storage};
use Illuminate\Http\UploadedFile;
final class GalleryTest extends TestCase{
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(!(config('database.default')==='sqlite'&&config('database.connections.sqlite.database')===':memory:')&&!(config('database.default')==='mysql'&&str_ends_with(config('database.connections.mysql.database'),'_test')))throw new \RuntimeException('Külön tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);foreach(['salon_state','media_assets','providers','calendar_connections','calendar_tasks','provider_security','provider_members','provider_password_tokens'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);Storage::fake('local');$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('g',40)])->withHeader('X-CSRF-TOKEN',str_repeat('g',40));}
 private function image(){return UploadedFile::fake()->createWithContent('photo.png',base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/NJ0AAAAASUVORK5CYII='));}
 public function test_gallery_limit_and_removal_are_enforced_on_server():void{for($i=0;$i<5;$i++)$this->post('/api/media',['target'=>'photo','image'=>$this->image()],['Accept'=>'application/json'])->assertCreated();$this->post('/api/media',['target'=>'photo','image'=>$this->image()],['Accept'=>'application/json'])->assertUnprocessable();$s=app(SalonStore::class)->read();$this->assertCount(5,$s['profile']['photos']);$first=$s['profile']['photos'][0];$this->deleteJson('/api/media',['target'=>'photo','url'=>'https://example.com/foreign.jpg'])->assertNotFound();$this->deleteJson('/api/media',['target'=>'photo','url'=>$first])->assertOk();$this->assertCount(4,app(SalonStore::class)->read()['profile']['photos']);$this->get('/media/'.basename($first))->assertNotFound();$this->post('/api/media',['target'=>'photo','image'=>$this->image()],['Accept'=>'application/json'])->assertCreated();}
 public function test_cover_can_be_removed_and_profile_api_cannot_bypass_gallery_limit():void{$cover=$this->post('/api/media',['target'=>'cover','image'=>$this->image()],['Accept'=>'application/json'])->assertCreated()->json('url');$this->deleteJson('/api/media',['target'=>'cover','url'=>$cover])->assertOk();$this->assertSame('',app(SalonStore::class)->read()['profile']['cover']);$photos=array_map(fn($n)=>'https://example.com/'.$n.'.jpg',range(1,6));$this->putJson('/api/profile',['photos'=>$photos])->assertUnprocessable();$this->assertEmpty(app(SalonStore::class)->read()['profile']['photos']??[]);$this->withSession(['admin'=>false]);$this->deleteJson('/api/media',['target'=>'cover','url'=>$cover])->assertForbidden();}
}
